"""Photo storage behind a small interface: local disk for dev, S3-compatible later (SPEC 7)."""

import re
from pathlib import Path
from typing import Protocol

# Keys are generated by us ("checks/<uuid>/<uuid>.jpg"), but validate anyway so a bug can
# never turn a key into a path outside the storage root.
_KEY_PATTERN = re.compile(r"^[a-z0-9-]+(/[a-z0-9-]+)*\.[a-z]+$")


class PhotoStorage(Protocol):
    def put(self, key: str, data: bytes) -> None: ...

    def get(self, key: str) -> bytes: ...

    def delete(self, key: str) -> None:
        """Remove the object. Deleting a missing key is not an error."""
        ...


def check_key(key: str) -> str:
    if not _KEY_PATTERN.match(key):
        raise ValueError(f"invalid storage key: {key!r}")
    return key


class LocalDiskStorage:
    def __init__(self, root: Path) -> None:
        self.root = root

    def _path(self, key: str) -> Path:
        return self.root / check_key(key)

    def put(self, key: str, data: bytes) -> None:
        path = self._path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)

    def get(self, key: str) -> bytes:
        return self._path(key).read_bytes()

    def delete(self, key: str) -> None:
        self._path(key).unlink(missing_ok=True)
